 const profiles=rows.map(([race,habitat,body,origin,civic,early,learning,routine,sense])=>({race,habitat,body,origin,civic,early,learning,routine,sense,strict:!civic,grasp:['hands','claws','many'].includes(body),water:['reef','river','ocean'].includes(habitat),...habitats[habitat],learningSkill:learning}));
 const nativeScenes=Object.values(habitats).filter(h=>h.scene!=='kitchen').map(h=>h.scene);
 const hash=(seed,n)=>{let x=Math.imul((seed^Math.imul(n+1,1597334677))>>>0,2654435761);return Math.imul(x^(x>>>16),2246822507)>>>0},profile=s=>profiles[typeof s==='number'?s:s.race]||profiles[0],bio=s=>Engine.biological(s);
 function ensure(s){if(!s.ecology){const p=profile(s);s.ecology={version:1,mode:'native',learning:'native',lastQuarter:-1,birthRealm:s.homeKingdom??s.kingdom,migrated:!!(s.age||s.turn)}}return s.ecology}
 function rollRealm(s,roll){const p=profile(s);if(s.race===0)return Math.floor(roll*KINGDOMS.length);return p.realms[Math.floor(roll*p.realms.length)]}
 function native(s){return s.race!==0&&profile(s).strict&&s.ecology?.mode!=='exchange'}
 function home(s){const p=profile(s);return p.label+'ใน'+KINGDOMS[s.kingdom][0]}
 function kinRace(s,race,slot=0){const p=profile(s);if(!p.water||profile(race).water)return race;const list=p.habitat==='river'?[28,41]:p.habitat==='reef'?[8,50,69]:[8,50,57];return list[hash(s.seed,slot+321)%list.length]}
 function birth(s){ensure(s);if(profile(s).strict&&s.household)s.household.originNote='สมาชิกของ'+RACES[s.race][0]+'ดูแลกันใน'+home(s)+' โดยถ่ายทอดวิธี'+profile(s).learningSkill;for(const m of s.household?.members||[]){if(profile(m.race).strict){m.nativeOccupation=occupation(m.race,m.id);m.adultOccupation=m.nativeOccupation;if(Engine.ageEquivalent(FamilyWorld.age(s,m),m.race)>=18)m.occupation=m.nativeOccupation}}}
 function occupation(race,id){const p=profile(race);return (id==='guardian'?'ผู้เฝ้าถิ่นและดูแลสมาชิกใหม่ · ':'ผู้ดูแลเสบียงและเส้นทาง · ')+p.label}
 function canTravel(s,k){return s.race===0||!profile(s).strict||profile(s).realms.includes(k)}
 function careerRole(name){if(/นักเวท|จอมเวท|นักพยากรณ์|ผู้ร่าย/.test(name))return 'ใช้แกนเวทอ่านความเปลี่ยนแปลงและส่งสัญญาณให้ผู้ร่วมงาน';if(/กวี|นักดนตรี|ผู้ส่งสาร/.test(name))return 'ใช้เสียงและสัญญาณที่ร่างสร้างได้ถ่ายทอดเรื่องให้ชุมชน';if(/นักสำรวจ|ผู้นำทาง|ผู้พิทักษ์|ผู้เฝ้า/.test(name))return 'สำรวจทางที่ร่างใช้ได้และส่งสัญญาณเตือนผู้ร่วมถิ่น';if(/นักการทูต|ทูต/.test(name))return 'สื่อสารเงื่อนไขร่วมกับตัวแทนที่รับรู้ต่างกันโดยรอให้อีกฝ่ายตอบครบ';return null}
 function allowedCareer(s,index){if(s.race===0)return true;const p=profile(s),j=JOBS[index];if(!j)return false;if(index>=114)return careerRows[index-114]?.habitats.includes(p.habitat)||false;if(p.strict&&s.ecology?.mode==='exchange'&&careerRole(j[0]))return true;if(!p.strict)return !p.water||!/ตีอาวุธ|ตีเกราะ|เตาหลอม|คนขับ|เกวียน|เรือเหาะ/.test(j[0]);return false}
 function autoJobs(s,items){return items.filter(({i})=>allowedCareer(s,i))}
 function moneyCost(s){return native(s)?0:1}
 function stage(s,min){const p=profile(s);if(s.race===0)return null;if(p.body==='quad')return ['ลูกอ่อนของฝูง','วัยก้าวแรก','วัยฝึกอ่านถิ่น','วัยทดลองแยกฝูง','โตเต็มวัย','ผู้นำทางที่ชำนาญ','ผู้อาวุโสของฝูง'][[0,2,6,13,18,40,65].indexOf(min)]||'ลูกอ่อนของฝูง';const labels=p.origin==='egg'||p.origin==='roe'?['ระยะแรกฟัก','วัยเริ่มใช้ร่าง','วัยฝึกใช้ร่าง','วัยแยกทางสั้น','โตเต็มวัย','วัยชำนาญถิ่น','ผู้อาวุโสของรัง']:['awaken','crystal','ember','sand','ink','spore','seed','bud'].includes(p.origin)?['เริ่มก่อรูป','คงรูปด้วยตนเอง','วัยเรียนรู้สัญญาณ','วัยกำหนดทางตน','คงตัวเต็มกำลัง','วัยสั่งสมประสบการณ์','ผู้รักษาความทรงจำถิ่น']:['วัยพึ่งพาผู้ดูแล','วัยเริ่มใช้ร่าง','วัยเรียนรู้ถิ่น','วัยฝึกอยู่นอกเขตพัก','โตเต็มวัย','วัยชำนาญถิ่น','ผู้อาวุโสของถิ่น'];return labels[[0,2,6,13,18,40,65].indexOf(min)]||labels[0]}
 function growth(s,min,person){const p=profile(s);if(s.race===0)return null;const forms={egg:'เปลือกไข่ที่ป้องกันร่างอ่อน',roe:'ถุงฟักในเขตน้ำที่กระแสไม่แรง',birth:p.body==='quad'?'เขตคลอดของฝูงบนพื้นซึ่งไม่ลื่น':'เขตพักซึ่งผู้ดูแลคอยอยู่ใกล้',bud:'ส่วนแตกหน่อซึ่งยังพึ่งแกนเดิม',seed:'เมล็ดและรากที่ยึดดินชื้น',spore:'สปอร์ซึ่งเริ่มเชื่อมกับใยถิ่น',awaken:'แกนที่เริ่มตอบรับชื่อของตน',crystal:'ผลึกอ่อนซึ่งยังต้องรักษาอุณหภูมิ',ember:'แกนเปลวซึ่งยังไม่มั่นคง',sand:'เม็ดทรายแกนที่ยังแยกตามลม',ink:'กลุ่มหมึกซึ่งยังต้องรักษาขอบร่าง'};
  const lines={0:['การถือกำเนิดของ'+RACES[s.race][0],`คุณเริ่มชีวิตจาก${forms[p.origin]} ใน${home(s)} ${person}อยู่ใกล้คอยตอบรับสัญญาณแรก`],2:[p.early,`${p.early} ${person}พาไปลองในเขตพักที่เหมาะกับร่างของคุณ`],6:['บทเรียนแรกของ'+RACES[s.race][0],`คุณฝึก${p.learningSkill}ที่${p.learning} ${person}คอยส่งสัญญาณจนคุณจำทางกลับได้`],13:['ทางสั้นที่เริ่มเลือกเอง',`คุณลอง${p.learningSkill}ไกลจากเขตพักขึ้นเล็กน้อย แล้วกลับไปถ่ายทอดสิ่งที่สังเกตให้กลุ่มฟัง`],18:['เติบโตในวิถีของ'+RACES[s.race][0],`คุณดูแลร่างและหาแหล่งดำรงชีวิตของตนได้มากขึ้น ${p.routine}`],40:['ผู้ที่เริ่มจำถิ่นได้ละเอียด',`คุณจำ${p.sense}ได้แม้ฤดูกาลเปลี่ยน กลุ่มเริ่มถามคุณก่อนเลือกทางใหม่`],65:['จังหวะพักของผู้อาวุโส',`คุณเลือกเขตพักที่ใช้แรงน้อยลงและถ่ายทอดวิธี${p.learningSkill}ให้ผู้ที่เริ่มฝึก ส่วนที่ร่างรับไม่ไหวมีคนในกลุ่มช่วยรับช่วง`]};const a=lines[min];return a?{title:a[0],paragraphs:[a[1]],kind:'growth',key:'growth-'+min,scene:p.scene,ecology:true}:null;
 }
 function learningLabel(s,key){const p=profile(s);if(s.race===0)return LifeGrowth.educationLabels[key];return {home:'เรียนรู้กับผู้ดูแลใน'+p.label,community:p.learning,apprentice:'ฝึกทักษะกับผู้ชำนาญในถิ่น',academy:'เรียนวิชาร่วมกับชุมชนต่างเผ่า',self:'สังเกตและทดลองในถิ่นของตน'}[key]||p.learning}
 function chooseMode(s,mode){if(s.race===0||!['native','exchange'].includes(mode)||s.dead||!s.accepted||s.calendar?.pending||s.outcome||bio(s)<18||ensure(s).mode===mode)return false;s.ecology.mode=mode;if(typeof RaceDrives!=='undefined')RaceDrives.ensure(s).legacyCash=false;Narrative.append(s,{title:mode==='native'?'กลับมาใช้วิถีของถิ่น':'เริ่มร่วมงานกับชุมชนต่างเผ่า',paragraphs:[mode==='native'?'คุณกลับมาจัดการดำรงชีวิตตามสภาพของ'+home(s):'คุณติดต่อชุมชนที่มีพื้นที่รองรับร่างของคุณ โดยยังรักษาถิ่นพักใน'+home(s)],kind:'decision',key:'ecology-mode-'+s.calendar.count,scene:profile(s).scene,ecology:true});return true}
 function daily(s){if(s.race===0)return null;if(typeof RaceDrives!=='undefined'&&(s.calendar?.count||0)%3===2){const page=RaceDrives.nativePage(s);if(page)return page}const p=profile(s),age=bio(s),n=s.calendar?.count??s.turn,which=hash(s.seed,n+212)%8,relative=(s.household?.members||[]).find(m=>m.alive),who=relative?.name||'ผู้ชำนาญในถิ่น';let a;
 if(age<2){const lines=[['สัญญาณที่ตอบกลับมา',who+'อยู่ใกล้จนคุณเริ่มจำ'+p.sense+'ได้'],['เขตพักของสมาชิกใหม่','กลุ่มดูแลสภาพของ'+p.label+'ให้เหมาะกับร่างที่กำลังก่อรูป คุณเริ่มแยกสัญญาณใกล้ตัวออกจากความเงียบ'],['จังหวะพักที่ยังสั้น','คุณรับรู้สิ่งใหม่อยู่ครู่หนึ่งก่อนกลับไปพัก '+who+'เฝ้าอยู่ในระยะที่รับรู้ถึงกันได้']];a=lines[n%3]}
 else if(age<6){a=[p.early,p.early+' คุณลองขยับตามวิธีของตน แล้วหยุดพักใน'+p.label+'เมื่อเริ่มล้า']}
 else {const lines=[['บทฝึกที่ได้ลองอีกครั้ง','คุณฝึก'+p.learningSkill+' วันนี้ทำได้ไกลกว่าเดิมนิดหนึ่งก่อนกลับเขตพัก'],['สิ่งที่ร่างบอก','คุณรับรู้'+p.sense+' จึงปรับจังหวะของตนก่อนฝืนไปต่อ'],['ช่วงหนึ่งในถิ่นของเรา',p.routine],['ทางกลับที่คุ้นเคย','หลังออกไปสำรวจ คุณใช้'+p.sense+'ตามทางกลับสู่'+p.label],['เวลาข้าง ๆ '+who,who+'อยู่ในแนวพักเดียวกัน คุณส่งสัญญาณทักตามวิธีของเผ่าก่อนพักด้วยกัน'],['สิ่งที่ถ่ายทอดต่อกัน',age<18?who+'สาธิตวิธี'+p.learningSkill+' คุณลองตามในเขตที่คุ้นเคย':'ผู้เริ่มฝึกมาขอดูวิธี'+p.learningSkill+' คุณให้ลองส่วนที่ร่างของเขารับไหว'],['วันที่สภาพถิ่นเปลี่ยน','กระแสและอุณหภูมิใน'+p.label+'ต่างจากครั้งก่อน คุณสำรวจจุดพักสำรองก่อนพากลุ่มผ่าน'],['สิ่งที่เก็บไว้ให้ถิ่น',p.routine+' ก่อนจบช่วงนี้คุณกันพื้นที่และแหล่งดำรงชีวิตส่วนหนึ่งไว้ให้สมาชิกอื่น']];a=lines[which]}
 if(age>=6&&typeof EcologyDays!=='undefined'){const pool=EcologyDays[p.habitat],inc=pool?.[hash(s.seed,n+867)%pool.length];if(inc&&which<5)a=inc;if(age>=18&&s.job!==null&&which===5){const j=careerRows.find(j=>j.index===s.job);if(j)a=[JOBS[s.job][0]+' · งานในถิ่น','คุณ'+j.tasks[hash(s.seed,n+441)%j.tasks.length]+' ก่อนส่งสัญญาณให้ผู้ร่วมงานรับช่วง']}if(which===7&&relative)a=['ช่วงพักกับ'+who,who+'ส่งสัญญาณคุ้นเคยมา คุณพักใกล้กันและลองถ่ายทอดเรื่อง'+p.sense+'ที่เพิ่งพบวันนี้'];}
 return {title:a[0],paragraphs:[a[1]],kind:age<6?'home':'daily',key:'eco-day-'+s.race+'-'+Math.floor(age/6)+'-'+which+'-'+hash(s.seed,n+867)%4,scene:p.scene,ecology:true};}
 const genericHuman=/ขอบโต๊ะ|เก้าอี้|เสื้อ|รองเท้า|กระดุม|กำชายผ้า|โต๊ะเรียน|ยกมือถาม|จับดินสอ|โรงเรียน|ห้องเรียน|ปั่นจักรยาน|รับกุญแจ|ค่าเช่า|เตียง|ช้อน|พิณ|บัตรงาน/;
 function entry(s,e){if(s.race!==0&&profile(s).strict&&e.kind==='loss'&&e.key?.startsWith('family-loss-')){const m=s.household?.members.find(m=>'family-loss-'+m.id===e.key);return {...e,ecology:true,scene:profile(s).scene,paragraphs:[(m?.name||'ผู้ร่วมถิ่น')+'ไม่ส่งสัญญาณตอบจากแนวพักอีกแล้ว ร่องรอยที่เคยใช้กลับถิ่นยังคงอยู่','กลุ่มยังจำ'+(m?.trait||'จังหวะที่ใช้เรียกกัน')+'ได้ และเว้นพื้นที่ให้ผู้ที่ยังคิดถึงเขา']}}if(s.race===0||e.ecology||e.kind==='loss'||e.kind==='world')return e;const p=profile(s);if(!p.strict&&bio(s)>=18)return e;const text=(e.paragraphs||[]).join(' ');if(e.kind==='work'&&p.strict){if(typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s))return {...e,...(RaceDrives.nativePage(s)||daily(s)),ecology:true};if(e.key?.startsWith('business-')){const b=s.livelihood?.business,def=Livelihood.businessCatalog.find(d=>d.id===b?.id);if(def){e.paragraphs=['คุณกับผู้ร่วมงานตรวจแหล่งดำรงชีวิตและบริการของ'+def.name+' รายรับช่วงล่าสุด '+b.lastRevenue+' ทอง ต้นทุน '+b.lastCosts+' ทอง'];e.scene=p.scene;e.ecology=true}return e}const j=careerRows.find(j=>j.index===s.job),task=j?j.tasks[hash(s.seed,s.calendar?.count??s.turn)%j.tasks.length]:careerRole(JOBS[s.job]?.[0]||'')||p.learningSkill;e.paragraphs=['คุณ'+task+'ใน'+home(s)+' ก่อนส่งสัญญาณให้ผู้ร่วมงานรับช่วง'];e.scene=p.scene;e.ecology=true;return e}if(['automatic','daily','home','training','heritage','arc','story','relationship','memory'].includes(e.kind)&&genericHuman.test(text)){const a=daily(s);return {...e,title:a.title,paragraphs:a.paragraphs,scene:p.scene,ecology:true}}
  if(p.strict&&e.kind==='companion'){e.paragraphs=['คุณกับสหายค่อย ๆ เรียนรู้สัญญาณของกันและกันใน'+p.label+' โดยเว้นจุดพักและแหล่งดำรงชีวิตที่เหมาะกับทั้งคู่'];e.scene=p.scene;e.ecology=true}if(p.strict&&e.kind==='purchase'){e.paragraphs=['คุณแลกสิ่งที่เหมาะกับร่างและ'+p.label+' แล้วลองใช้อย่างค่อยเป็นค่อยไปก่อนจัดไว้ในเขตพัก'];e.scene=p.scene;e.ecology=true}
  if(e.kind==='growth')return {...e,...growth(s,Number((e.key||'').slice(7)),(s.household?.members||[]).find(m=>m.alive)?.name||'ผู้ดูแลถิ่น')};return e;
 }
 function eventAllowed(s,e){if(e.ecologyNative&&!profile(s).strict)return false;if(e.ecologyOnly!==undefined)return s.race===e.ecologyOnly;if(s.race===0)return true;const p=profile(s);if(e.id==='exp11-child-lunch'&&(p.strict||['awaken','crystal'].includes(p.origin)))return false;if(typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s)&&e.moneyOnly)return false;if(e.bondOnly)return true;if(e.id==='school')return false;if(!p.strict)return true;if(e.projectOnly)return projectAllowed(s,e.projectOnly);if(Number.isInteger(e.rankOnly)||Number.isInteger(e.householdOnly))return false;if(e.id==='school'||e.id==='academy'||e.id==='human-road')return false;if(e.moneyOnly&&['money-roof','money-tools','money-wedding','money-coat','money-lesson','money-fire','money-house','money-research'].includes(e.id))return false;
  const words=[e.title,e.text,...(e.choices||[]).flatMap(c=>[c.label,c.success,c.fail])].join(' ');if(genericHuman.test(words)&&!e.ecology&&e.relationOnly===undefined)return false;return true;
 }
 function scene(s,e,env){const p=profile(s);if(s.race===0)return env;if(nativeScenes.includes(env))return env;if(['classroom','study'].includes(env)&&s.ecology?.learning==='exchange'&&p.grasp&&!p.water)return env;if(['nursery','bedroom','kitchen','study','classroom','garden'].includes(env))return p.scene;if(p.strict&&['music','library','guild','workshop','farm','alchemy','clinic','council','shrine'].includes(env))return p.scene;return env}
 function businessAllowed(s,def){return !profile(s).strict||!!def?.ecology}
 function projectAllowed(s,id){return s.race===0||!profile(s).strict||['recovery','living-map','dragon-refuge'].includes(id)}
 function petAllowed(s,p){return !profile(s).water||['fish','octopus','crab','axolotl','turtle','frog','otter','seahorse'].includes(p.shape)||p.category==='aquatic'}
 function itemAllowed(s,i){if(i.ecologyHabitats)return i.ecologyHabitats.includes(profile(s).habitat);if(!profile(s).strict)return !profile(s).water||!['hearth','oven','anvil'].includes(i.id);if(i.ecologyHabitats)return i.ecologyHabitats.includes(profile(s).habitat);return ['herb-box','garden-bed','crystal-tree'].includes(i.id)&&['root','glade','tree'].includes(profile(s).habitat)||i.id==='egg-warmer'&&['ember','cave'].includes(profile(s).habitat)}
 function migrate(s){const old=!s.ecology;ensure(s);if(!old||s.race===0)return;const p=profile(s);if(s.flags?.academy&&p.grasp&&!p.water)s.ecology.learning='exchange';for(const e of s.diary?.entries||[]){if((p.strict||Engine.ageEquivalent(e.age,s.race)<18)&&genericHuman.test((e.paragraphs||[]).join(' '))&&e.kind!=='loss')e.legacyEcologyMismatch=true}const invalid=new Set((s.diary?.entries||[]).filter(e=>e.legacyEcologyMismatch).map(e=>(e.key||'').replace(/^decision-/,'')));for(const e of s.lifeLegacy?.entries||[])if(invalid.has((e.key||'').replace(/^decision-/,'')))e.legacyEcologyMismatch=true;for(const list of [s.diary?.memories,s.stories?.memories])if(Array.isArray(list))for(let i=list.length-1;i>=0;i--)if(invalid.has(list[i].id))list.splice(i,1);for(const m of s.household?.members||[]){const mp=profile(m.race);if(mp.strict&&FamilyWorld.occupations.flat().includes(m.adultOccupation||m.occupation)){m.nativeOccupation=occupation(m.race,m.id);m.adultOccupation=m.nativeOccupation;m.occupation=m.nativeOccupation}}}
 function activity(s,key){const p=profile(s),who=(s.household?.members||[]).find(m=>m.alive)?.name||'ผู้ร่วมถิ่น';if(s.race===0)return null;const labels={family:['ช่วงเวลาร่วมถิ่น',who+'อยู่ในเขตพักใกล้กัน คุณส่งสัญญาณถามข่าวและรับรู้เรื่องที่เขาอยากเล่า'],explore:['ทางสำรวจของ'+RACES[s.race][0],'คุณใช้'+p.sense+'สำรวจทางที่ยังไม่คุ้น แล้วทำเครื่องหมายด้วยวิธีที่ร่างของคุณใช้ได้'],practice:['ฝึก'+p.learningSkill,'คุณลอง'+p.learningSkill+'ในเขตที่คุ้นเคย จนเริ่มรู้ว่าควรพักก่อนฝืนตรงไหน'],rest:['พักใน'+p.label,p.routine+' หลังจากนั้นคุณพักให้ร่างคืนกำลังก่อนออกไปอีกครั้ง']};const v=labels[key];return v?{title:v[0],paragraphs:[bio(s)<4?who+'เฝ้าร่างที่กำลังเติบโตของคุณใน'+p.label:v[1]],kind:'interaction',scene:p.scene,ecology:true}:null}
 function spending(s,option){if(s.race===0||!profile(s).strict)return option;const p=profile(s),dict={meal:['แบ่งเสบียงและกำลังให้กลุ่ม','คุณเตรียมส่วนของแหล่งดำรงชีวิตใน'+p.label+'ไว้แบ่งกับคนใกล้ตัว โดยเลือกให้เหมาะกับรูปกายของแต่ละคน'],gift:['ของที่เหมาะกับคนในถิ่น','คุณนำของที่ผู้รับใช้ได้ไปวางในจุดรับของ เขาส่งสัญญาณตอบกลับเมื่อพบมัน'],clinic:['ดูแลร่างกับผู้ชำนาญ','ผู้ชำนาญช่วยตรวจร่างตามสัญญาณของ'+RACES[s.race][0]+' แล้วให้คุณพักในสภาพที่เหมาะสม'],course:['ฝึกวิถีของถิ่นกับผู้ชำนาญ','คุณใช้ทุนฝึก'+p.learningSkill+'กับผู้ชำนาญ โดยทดลองในสภาพถิ่นจริง'],hobby:['ฝึกสิ่งที่ร่างทำแล้วเพลิดเพลิน','คุณฝึกทำนองและสัญญาณที่ตนถนัดโดยไม่ต้องใช้เครื่องมือซึ่งจับไม่ได้'],garden:['ฟื้นแหล่งดำรงชีวิตของถิ่น','คุณร่วมฟื้นความสะอาดและสภาพแหล่งดำรงชีวิตใน'+p.label+' เพื่อให้สมาชิกกลุ่มกลับมาใช้ได้'],trip:['สำรวจแนวถิ่นใกล้เคียง','คุณออกไปยังส่วนของ'+p.label+'ที่ไม่คุ้น แล้วกลับมาตามสัญญาณเดิมของกลุ่ม'],donation:['ช่วยเสบียงและจุดพักร่วม','ทุนที่คุณแบ่งให้ถูกใช้ดูแลสมาชิกที่ยังหาแหล่งดำรงชีวิตเองไม่ได้'],tools:['เครื่องช่วยที่รองรับรูปกาย','คุณเลือกเครื่องช่วยรับสัญญาณที่ใช้ได้กับร่างของคุณ แล้วลองฝึก'+p.learningSkill],renovate:['ปรับเขตพักให้เหมาะกับร่าง','คุณร่วมจัดพื้นที่ใน'+p.label+'ให้พักได้โดยไม่เสียกำลังกับสภาพที่รบกวนร่าง'],house:['สิทธิใช้ถิ่นพักถาวร','คุณรับสิทธิใช้เขตพักใน'+p.label+' และจัดจุดยึดหรือเส้นทางกลับที่ตนจดจำได้'],heritage:['พิธีสืบวิถีของเผ่า','คุณร่วมส่งสัญญาณและฟังเรื่องของถิ่นตามวิธีที่'+RACES[s.race][0]+'รับรู้ได้']};const a=dict[option.id];return a?{...option,name:a[0],text:a[1],scene:p.scene}:option}
 const nativeDreams=Object.entries(habitats).filter(([k])=>k!=='town').map(([k,h])=>'ฟื้น'+h.label+'ให้สมาชิกใหม่พักได้');
 function bondDream(race,h,fallback){const p=profile(race);if(p.strict&&typeof RaceDrives!=='undefined')return RaceDrives.profile(race).paths[['inherit','coexist','self'][h%3]];return p.strict?'ฟื้น'+p.label+'ให้สมาชิกใหม่พักได้':fallback}
 function bondPreference(race,h,fallback){const p=profile(race);if(!p.strict)return fallback;return p.water?['เปลือกหอยเรียบ','หินแร่จากแอ่งน้ำ','สาหร่ายที่ใช้บอกทาง'][h%3]:p.habitat==='ember'?['หินเก็บความอุ่น','แร่ที่ทนเปลวไฟ','ถ่านไม้หอม'][h%3]:p.body==='shade'?['หินยึดแสง','ผลึกเก็บเสียง','เครื่องหมายของถิ่น'][h%3]:['หินบอกทาง','เมล็ดจากถิ่นเดิม','ของซึ่งเก็บสัญญาณคุ้นเคย'][h%3]}
 function dreamBeats(dream,race){if(typeof RaceDrives!=='undefined'&&Number.isInteger(race)){const goal=RaceDrives.profile(race),stance=Object.keys(goal.paths).find(k=>goal.paths[k]===dream);if(stance)return stance==='inherit'?['เขาเริ่มหาผู้ร่วมทางเพื่อ'+dream,'ผู้ที่เสียส่วนแบ่งตั้งคำถามกับแผน เขาต้องตัดสินใจว่าจะรับฟังขอบเขตใด','แผนจะ'+dream+'มีผู้รับช่วงในกลุ่ม แต่ผลต่อผู้ที่อยู่นอกกลุ่มยังไม่จบเพียงคำประกาศ']:stance==='coexist'?['เขาเริ่มส่งสัญญาณให้กลุ่มต่างถิ่นรับรู้แผนจะ'+dream,'ทั้งสองฝ่ายลองขอบเขตที่ตกลงกัน และบอกส่วนที่ยังทำร้ายร่างของตน','ทางที่จะ'+dream+'เริ่มมีคนใช้ต่อ แม้ยังต้องทบทวนเมื่อถิ่นเปลี่ยน']:['เขาเริ่มเว้นระยะจากสิ่งที่วงศ์เคยกำหนด เพื่อ'+dream,'เขาพบว่าสิ่งที่เลือกเองก็มีราคาที่ต้องรับ โดยไม่โยนให้ผู้ดูแลเดิม','เขาเริ่ม'+dream+'ได้จริง และยังเลือกว่าจะรักษาสายใดกับถิ่นเดิม'];}if(!nativeDreams.includes(dream)){if(Number.isInteger(race)&&profile(race).strict)return ['เขาหาผู้ร่วมงานที่ช่วยทำแผนจะ'+dream+'ให้เข้ากับร่างของแต่ละฝ่าย','ผู้ร่วมงานรับช่วงสิ่งที่ร่างของเขาทำไม่ได้ เขาเริ่มมีส่วนที่ดูแลเองได้','แผนจะ'+dream+'เริ่มเป็นจริงผ่านความร่วมมือของหลายรูปกาย เขายังจำส่วนที่คุณช่วยไว้'];return null;}return ['เขาสำรวจจุดพักที่เหมาะกับสมาชิกใหม่และเริ่มเก็บส่วนที่เป็นอันตราย','เขาทดลองให้สมาชิกกลุ่มเข้าพักและปรับสภาพตามสัญญาณที่ได้รับ','ถิ่นพักที่เขาดูแลรับสมาชิกใหม่ได้แล้ว คนในกลุ่มยังจำส่วนที่คุณช่วยไว้']}
 function bondText(s,p,r,action){if(s.race===0&&!profile(p.race).strict||!profile(s).strict&&!profile(p.race).strict)return null;const texts={listen:'คุณกับ'+r.name+'อยู่ในระยะที่สื่อสารถึงกัน เขาเล่าเรื่องที่อยาก'+p.dream+'จนจบ',gift:'คุณนำ'+p.preference+'ไปยังจุดที่'+r.name+'รับได้ เขาตอบกลับด้วยสัญญาณที่คุณคุ้นเคย',help:'คุณช่วย'+r.name+'ดูแลส่วนของถิ่นซึ่งเกี่ยวกับแผนจะ'+p.dream,visit:r.distance?'คุณฝากข่าวกับผู้เดินทางที่รู้จักเพื่อส่งต่อถึง'+r.name:'คุณพบ'+r.name+'ที่แนวพักร่วม ก่อนออกสำรวจช่วงสั้นไปด้วยกัน',apologize:'คุณส่งสัญญาณขอฟังเรื่องที่'+r.name+'เสียใจ แล้วอธิบายสิ่งที่ตนทำพลาดจนทั้งสองฝ่ายเข้าใจกัน'};return texts[action]||null}
 function bondMoment(s,p,r,n){if(!profile(s).strict&&!profile(p.race).strict)return null;const a=profile(p.race),entries=[['สัญญาณจากคนคุ้นเคย',r.name+'ส่งสัญญาณทักจากแนวพัก คุณตอบด้วยจังหวะที่ใช้ระหว่างกัน'],['ของที่พบในทางเดิม',r.name+'นำ'+p.preference+'มาฝากไว้ในจุดที่คุณรับได้'],['แผนของถิ่นในฤดูถัดไป',r.name+'อยาก'+p.dream+' วันนี้เขาชวนสังเกตพื้นที่ซึ่งกำลังเปลี่ยน'],['ช่วงพักที่ไม่ต้องรีบ',r.name+'อยู่ในแนวพักใกล้กัน ทั้งคู่ต่างพักตามจังหวะที่ร่างต้องการ'],['ข่าวจากอีกแนวถิ่น',r.name+'ฝากข่าวว่าสภาพถิ่นช่วงนี้เปลี่ยนไป คุณจำสัญญาณที่เคยใช้กลับทางนั้นได้'],['สิ่งที่สังเกตให้กัน',r.name+'สังเกตว่าคุณเริ่มล้า จึงเปลี่ยนแนวพักให้เงียบลงก่อนคุยต่อ']];return {title:entries[n%6][0],text:entries[n%6][1],scene:a.scene}}
 function decorateBond(s,e){if(!profile(s).strict||!e.bondOnly)return e;const spec={keepsake:['สัญญาณเรียกที่ขาดช่วง','แนวฝึกที่มีคนกีดกัน','สัญญาณเก่าก่อนแยกถิ่น'],recipe:['แหล่งดำรงชีวิตที่กลุ่มจำได้','ฤดูที่หาได้ไม่เท่าเดิม','สิ่งที่เก็บไว้ส่งต่อกลุ่ม'],instrument:['ทำนองที่ยังรับกันไม่ทัน','สัญญาณต่อหน้าผู้ร่วมถิ่น','ทำนองที่มีคนตอบกลับ'],credit:['รอยทางที่ช่วยกันสำรวจ','คนที่ไม่ได้ถูกเอ่ยชื่อ','เส้นทางที่กลุ่มใช้ต่อได้'],departure:['ข่าวว่าจะย้ายแนวถิ่น','สัญญาณจากที่ไกล','เมื่อกลับมาพบกันอีก'],care:['คนที่เริ่มใช้แรงมากขึ้น','จุดพักซึ่งยังกลับไปไม่ไหว','ช่วงเวลาที่เลือกอยู่ด้วยกัน'],rift:['สัญญาณที่ทำให้อีกฝ่ายเสียใจ','ทางที่ต้องพบกันอีก','เรื่องที่เขาเริ่มสื่อสารอีกครั้ง'],garden:['เขตพักที่ตกลงดูแลด้วยกัน','สภาพที่เริ่มรบกวนร่าง','กลับมาดูแลแนวพักอีกครั้ง']},step=e.bondOnly.step,names=spec[e.bondOnly.story];if(!names)return e;const p=profile(s),texts=['{npc}อยากให้คุณช่วยดูแลส่วนหนึ่งของ'+p.label+' แต่คุณกับเขาต้องหาวิธีที่ร่างของแต่ละฝ่ายร่วมมือกันได้','สภาพถิ่นเปลี่ยนจากครั้งก่อน {npc}ส่งสัญญาณให้คุณมาดูสิ่งที่เคยทำร่วมกัน','{npc}กลับมาพบที่แนวพักเดิม เรื่องที่เคยร่วมกันทำมีคนในกลุ่มนำไปใช้ต่อ'];return {...e,title:names[step],text:texts[step],scene:p.scene,ecology:true,choices:e.choices.map((c,i)=>({...c,label:[step===0?'ช่วยลงมือและรับฟังกัน':step===1?'ปรับแผนร่วมกับเขา':'ทำส่วนที่ส่งต่อให้กลุ่มได้','หาวิธีที่ตนกับเขารับไหว','แยกขอบเขตแล้วรักษาระยะที่ตกลงกัน'][i],success:['คุณกับ{npc}ทำส่วนที่ร่วมมือกันได้ และส่งสัญญาณบอกคนในกลุ่มให้รับช่วง','คุณกับ{npc}ปรับแผนจนใช้แรงและแหล่งดำรงชีวิตเท่าที่มี','คุณกับ{npc}ตกลงเขตของแต่ละฝ่ายโดยไม่ต้องฝืนร่างหรือรับปากเกินกำลัง'][i],...(c.promise?{promise:{...c.promise,text:'ดูแลแนวพักตามที่ตกลง'}}:{})}))}}
 function projectInfo(s,id){if(!profile(s).strict)return null;const p=profile(s);if(id==='living-map')return {name:'เส้นทางที่กลุ่มรับรู้ร่วมกัน',description:'สำรวจด้วย'+p.sense+' แล้วส่งต่อทางที่ร่างของแต่ละฝ่ายใช้ได้',stages:[{title:'ทางที่ยังยืนยันไม่ได้',text:'คุณกับ {npc} พบว่าทางเดิมใน'+p.label+'เปลี่ยนไป คุณจะตรวจด้วย'+p.learningSkill+'อย่างไร',labels:['ย้อนทดสอบแนวที่คุ้นเคย','ขอผู้รู้ถิ่นนำไปสำรวจ','ฝากสัญญาณว่ายังไม่ยืนยัน'],results:['คุณกับ{npc}ทดสอบทางเดิมทีละช่วงและบอกส่วนที่ร่างของตนผ่านไม่ได้','คุณกับผู้รู้ถิ่นตรวจทางร่วมกัน แต่ละฝ่ายช่วยอธิบายสัญญาณที่อีกฝ่ายรับรู้ไม่ได้','กลุ่มรู้ว่าทางนี้ยังใช้ไม่ได้แน่นอน จึงยังไม่พาสมาชิกใหม่ผ่าน']},{title:'ผู้เดินทางที่รับรู้ต่างกัน',text:'สัญญาณที่คุณใช้จำทางไม่ชัดสำหรับผู้มาเยือน {npc} ชวนเลือกวิธีส่งต่อโดยไม่ให้ใครต้องเดา',labels:['ทดลองทางกับผู้มาเยือน','แยกสัญญาณตามรูปกาย','เว้นเส้นทางเสี่ยงไว้ก่อน'],results:['ผู้มาเยือนลองทางโดยมีคุณเฝ้าอยู่ คุณจึงพบจุดซึ่งต้องอธิบายเพิ่ม','กลุ่มเพิ่มสัญญาณที่รับรู้ได้ต่างวิธี แทนการให้ทุกคนใช้แบบเดียว','ทางสั้นที่สุดยังไม่เปิด แต่กลุ่มมีทางอ้อมที่ตรวจแล้ว']},{title:'ทางที่ยังใช้ได้เมื่อคุณไม่อยู่',text:'กลุ่มข้างเคียงเริ่มขอใช้เส้นทางใน'+p.label+' คุณจะส่งต่อสิ่งที่เรียนรู้อย่างไร',labels:['ถ่ายทอดให้ผู้เฝ้าถิ่นหลายกลุ่ม','ดูแลทางหลักของตนก่อน','แลกเปลี่ยนสิทธิใช้ทางอย่างชัดเจน'],results:['ผู้เฝ้าถิ่นเริ่มพากลุ่มผ่านโดยไม่ต้องรอคุณ ทุกคนยังตรวจสภาพก่อนใช้จริง','ทางหลักได้รับการดูแลต่อ คุณเหลือแรงพอค่อย ๆ ตรวจส่วนที่ยังไม่รู้','แต่ละกลุ่มรู้ขอบเขตที่ตกลงกันและส่งข่าวเมื่อสภาพถิ่นเปลี่ยน']} ]};
 if(id==='recovery')return {name:'จังหวะพักที่ร่างรับไหว',description:'สังเกต'+p.sense+'และปรับจังหวะดำรงชีวิตให้เข้ากับร่าง',stages:[{title:'สัญญาณล้าที่ไม่เหมือนเดิม',text:'แม้อยู่ใน'+p.label+' ร่างของคุณยังคืนกำลังไม่เหมือนก่อน {npc} ชวนสังเกตสภาพแวดล้อมกับแหล่งดำรงชีวิต',labels:['ให้ผู้รู้ร่างของเผ่าช่วยตรวจ','ลดช่วงฝึกแล้วพักในจุดคุ้นเคย','แบ่งงานที่กลุ่มช่วยรับได้'],results:['คุณเริ่มแยกสิ่งที่รบกวนร่างได้ โดยไม่ต้องเดาอยู่คนเดียว','ร่างได้ช่วงพักที่ต่อเนื่องขึ้น คุณค่อย ๆ ลองเพิ่มแรงเท่าที่รับไหว','สมาชิกในกลุ่มรับช่วงบางส่วน การพักจึงไม่ต้องแลกกับการหายไปจากกลุ่ม']},{title:'พื้นที่ซึ่งยังกลับไปไม่ไหว',text:'ส่วนหนึ่งของถิ่นยังทำให้คุณล้าเร็ว {npc} ถามว่าจะรักษาสิ่งที่อยากทำโดยไม่ฝืนอย่างไร',labels:['ปรับแนวพักให้ใกล้แหล่งดำรงชีวิต','แบ่งช่วงทำกับช่วงคืนกำลัง','ขอผู้ร่วมถิ่นช่วยส่วนที่ลำบาก'],results:['ระยะที่ต้องใช้แรงลดลง คุณกลับมามีกำลังเหลือสำหรับสิ่งที่อยากทำ','คุณเริ่มรู้จังหวะก่อนร่างเสียกำลัง และหยุดได้ทันบ่อยขึ้น','สิ่งที่เคยทำลำพังกลายเป็นงานที่รับช่วงกันได้']},{title:'ใช้ชีวิตต่อในจังหวะใหม่',text:'คุณกับ {npc} เริ่มรู้ว่าส่วนใดของแผนช่วยจริง คุณอยากเก็บวิธีใดไว้ในชีวิตต่อจากนี้',labels:['รักษาขอบเขตที่ลองแล้วว่ารับไหว','ส่งต่อสิ่งที่สังเกตให้กลุ่ม','เหลือเวลาสำหรับสิ่งที่ยังอยากลอง'],results:['คุณยอมปล่อยงานบางส่วนเพื่อให้ร่างยังใช้ชีวิตได้ต่อเนื่อง','ผู้ที่เริ่มล้าในกลุ่มมีตัวอย่างให้ลอง โดยยังหาวิธีของร่างตนเอง','แผนใหม่มีทั้งช่วงคืนกำลังและพื้นที่สำหรับความอยากรู้อยากเห็น']} ]};return null;
 }
